[{"order":1,"type":"heading","text":"Performance Metrics & Web Vitals Monitoring via Selenium"},{"order":2,"type":"paragraph","text":"Monitoring Core Web Vitals (LCP, FID, CLS) and custom performance metrics during automated testing ensures that your web applications meet modern user experience standards. While Selenium is primarily designed for functional testing, it can execute JavaScript and access browser performance logs to extract real-time metrics."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"bullet_point","text":"Selenium WebDriver (Java, Python, or JavaScript bindings)"},{"order":5,"type":"bullet_point","text":"Chromium-based browser (Chrome or Edge) configured with performance logging capabilities enabled."},{"order":6,"type":"subheading","text":"Configuring ChromeOptions for Performance Logging"},{"order":7,"type":"paragraph","text":"To capture browser performance logs, you must initialize ChromeDriver with logging preferences enabled using ChromeOptions."},{"order":8,"type":"code","text":"ChromeOptions options = new ChromeOptions();
LoggingPreferences logPrefs = new LoggingPreferences();
logPrefs.enable(LogType.PERFORMANCE, Level.ALL);
options.setCapability("goog:loggingPrefs", logPrefs);
WebDriver driver = new ChromeDriver(options);"},{"order":9,"type":"subheading","text":"Extracting Navigation Timing API Metrics"},{"order":10,"type":"paragraph","text":"You can use Selenium to execute JavaScript that queries the window.performance API, retrieving key metrics such as DOM load time, page load time, and network latency."},{"order":11,"type":"code","text":"JavascriptExecutor js = (JavascriptExecutor) driver;
Long loadEventEnd = (Long) js.executeScript("return window.performance.timing.loadEventEnd;");
Long navigationStart = (Long) js.executeScript("return window.performance.timing.navigationStart;");
Long pageLoadTime = loadEventEnd - navigationStart;
System.out.println("Page Load Time: " + pageLoadTime + " ms");"},{"order":12,"type":"subheading","text":"Monitoring Core Web Vitals Using the Performance Observer API"},{"order":13,"type":"paragraph","text":"Core Web Vitals like Largest Contentful Paint (LCP) and Cumulative Layout Shift (CLS) require the PerformanceObserver API. You can inject a script via Selenium to listen to these metrics and store them in a global JavaScript variable for retrieval."},{"order":14,"type":"code","text":"String script = "window.cwvMetrics = {}; " +
    "const observer = new PerformanceObserver((list) => { " +
    "  for (const entry of list.getEntries()) { " +
    "    window.cwvMetrics[entry.entryType] = entry.startTime; " +
    "  } " +
    "}); " +
    "observer.observe({type: 'largest-contentful-paint', buffered: true});";
js.executeScript(script);"},{"order":15,"type":"subheading","text":"Retrieving and Asserting Metrics in Tests"},{"order":16,"type":"paragraph","text":"After navigating through your test scenarios, retrieve the collected metrics and assert that they fall within acceptable performance thresholds."},{"order":17,"type":"code","text":"Map<String, Object> metrics = (Map<String, Object>) js.executeScript("return window.cwvMetrics;");
Double lcp = (Double) metrics.get("largest-contentful-paint");
if (lcp != null) {
    assert lcp < 2500.0 : "LCP exceeded threshold: " + lcp;
}"},{"order":18,"type":"subheading","text":"Conclusion"},{"order":19,"type":"paragraph","text":"By integrating performance metrics and Web Vitals monitoring into your Selenium test suite, you can catch performance regressions early in the CI/CD pipeline before they impact real users."}]
